{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://semio.tech/schemas/flow/geometry/ownership",
  "title": "Supplied Geometry Port Ownership",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "copyGrants",
    "source",
    "expected"
  ],
  "properties": {
    "copyGrants": {
      "type": "array",
      "const": [
        1,
        3,
        64
      ]
    },
    "source": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "text",
        "capacityBytes"
      ],
      "properties": {
        "text": {
          "type": "string",
          "minLength": 1
        },
        "capacityBytes": {
          "type": "integer",
          "minimum": 8
        }
      }
    },
    "expected": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "utf8Bytes",
        "sourceIdentity",
        "zeroItems",
        "shortDepth",
        "shortCapacity",
        "shortRelease",
        "terminalBox",
        "physical"
      ],
      "properties": {
        "utf8Bytes": {
          "type": "integer",
          "const": 7
        },
        "sourceIdentity": {
          "type": "string",
          "const": "samePointer"
        },
        "zeroItems": {
          "type": "string",
          "const": "inert"
        },
        "shortDepth": {
          "type": "string",
          "const": "inert"
        },
        "shortCapacity": {
          "type": "string",
          "const": "inert"
        },
        "shortRelease": {
          "type": "string",
          "const": "inert"
        },
        "terminalBox": {
          "type": "string",
          "const": "separateAdmittedTurn"
        },
        "physical": {
          "type": "string",
          "const": "originalPlusAdmittedScaffolds"
        }
      }
    }
  }
}

