/** 🌐️ Validates supplied geometry ownership with strict schema and independent Unicode/JSON oracles. */
import {strict as assert} from "node:assert";
import stableStringify from "fast-json-stable-stringify";
import {semioSchemaAjvV1} from "../../../../../../../🔨️modules/🧬️schema/🔮️oracles/✅️validator/🟦️.ts";
const schema=await Bun.file(new URL("../../🧬️schema/♻️ownership/🔣️.json",import.meta.url)).json();
const fixture=await Bun.file(new URL("../../🧫️fixtures/♻️ownership/🔣️.json",import.meta.url)).json();
const validate=semioSchemaAjvV1({allErrors:true}).compile(schema);
assert(validate(fixture),JSON.stringify(validate.errors));
for(const field of ["zeroItems","shortDepth","shortCapacity","shortRelease","terminalBox","physical"]){
  const expected={...fixture.expected};delete expected[field];
  assert.equal(validate({...fixture,expected}),false,`missing ownership law ${field}`);
}
assert.equal(validate({...fixture,copyGrants:[0]}),false);
assert.equal(validate({...fixture,source:{...fixture.source,capacityBytes:7}}),false);
assert.equal(validate({...fixture,expected:{...fixture.expected,physical:"logicalBytes"}}),false);
assert.equal(validate({...fixture,expected:{...fixture.expected,unknown:true}}),false);
assert.equal(Buffer.byteLength(fixture.source.text),fixture.expected.utf8Bytes);
assert.equal(new TextEncoder().encode(fixture.source.text).length,fixture.expected.utf8Bytes);
assert.deepEqual(JSON.parse(stableStringify({value:fixture.source.text})),{value:fixture.source.text});
assert(fixture.source.capacityBytes>fixture.expected.utf8Bytes);
console.log("[DEBUG] original GeometryPort strictAjv=true rejectedMissingLaws=6 rejectedInvalidContracts=4 utf8Bytes=7 stableJson=true");
